def solve_shared_tail(text):
    tokens = text.split()
    n, a, b = int(tokens[0]), int(tokens[1]), int(tokens[2])
    nxt = [int(t) for t in tokens[3:3 + n]]

    def length(node):
        steps = 0
        while node != -1:
            steps += 1
            node = nxt[node]
        return steps

    la, lb = length(a), length(b)
    while la > lb:
        a, la = nxt[a], la - 1
    while lb > la:
        b, lb = nxt[b], lb - 1
    while a != b:
        a, b = nxt[a], nxt[b]
    return str(a)
